// Normaliza o payload. Kommo, widget de site e teste manual
// mandam formatos diferentes; o agente recebe sempre o mesmo.
//
// sessionId identifica a CONVERSA. O telefone identifica a PESSOA — e é ele
// que o agente usa para reconhecer alguém que já falou por outro canal.
const b = $input.first().json.body || $input.first().json;

const text = b.msgCustomer || b.chatInput || b.message || b.text || '';
const phone = b.phone || b.contact_phone || b.from || null;
const sessionId = b.sessionId || phone || b.lead_id || 'anon-' + Date.now();

if (!text.trim()) {
  // Mensagem vazia não vira turno. Evento de sistema do Kommo (mudança de
  // etapa, nota interna) chegaria aqui e o agente responderia ao nada.
  return [{ json: { skip: true, sessionId } }];
}

return [{ json: {
  skip: false,
  sessionId: String(sessionId),
  text: String(text).slice(0, 4000),
  channel: b.channel || 'whatsapp',
  contact_name: b.name || b.contact_name || null,
  contact_phone: phone,
  kommo_lead_id: b.lead_id ? Number(b.lead_id) : null
}}];

// Decide o que devolver ao canal.
//
// Três resultados que NÃO são uma resposta e não podem virar uma:
//   human_takeover  um humano assumiu — silêncio, não mensagem
//   error           o turno falhou — texto de fallback, nunca meia frase
//   HTTP != 200     agente fora do ar — fallback e alerta
const r = $input.first().json;
const status = r.statusCode ?? 200;
const body = r.body ?? r;

if (status !== 200) {
  return [{ json: {
    reply: "Sorry, something went wrong on my end. Someone from the team will pick this up shortly.",
    send: true, healthy: false, sessionId: body.sessionId || null,
    note: 'agent unreachable: HTTP ' + status
  }}];
}

if (body.mode === 'human_takeover') {
  // Silêncio deliberado. Mandar qualquer coisa aqui atropela o humano que
  // está atendendo.
  return [{ json: { reply: '', send: false, healthy: true,
                    sessionId: body.sessionId, note: 'human owns this conversation' }}];
}

return [{ json: {
  reply: body.output,
  send: Boolean(body.output),
  healthy: !body.error,
  sessionId: body.sessionId,
  mode: body.mode || null,
  escalated: Boolean(body.escalated)
}}];
